pages/cart:
---
cart: true
products:
    featured:
        limit: {{theme_settings.homepage_featured_products_count}}
---
{{inject 'cancelButtonText' (lang 'common.cancel')}}
{{#partial "page"}}
{{inject 'invalidEntryMessage' (lang 'cart.invalid_entry_message')}}
<div class="page">
    <div class="container">
        <main class="page-content" data-cart>
            {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}

            {{> components/cart/page-title}}

            <div data-cart-status>
                {{> components/cart/status-messages}}
            </div>

            {{#if cart.items.length}}
                <div class="loadingOverlay"></div>

                <div class="cart-container">
                    <div data-cart-content>
                        {{> components/cart/content}}
                        <div class="cart-recommendations">
                            {{#if products.featured}}
                                {{> components/products/featured-escapa-cart products=products.featured columns=theme_settings.homepage_featured_products_column_count}}
                            {{/if}}
                        </div>
                    </div>

                    <div data-cart-totals>
                        <div class="totals-container">
                            <h4 class="summary">{{lang 'cart.checkout.totals_summary'}}</h4>
                            {{> components/cart/totals}}
                            {{#if cart.show_primary_checkout_button}}
                                <div class="cart-actions">
                                    <a class="button button--primary" href="{{urls.checkout.single_address}}" title="{{lang 'cart.checkout.title'}}">{{lang 'cart.checkout.button'}}</a>
                                    {{#if cart.show_multiple_address_shipping}}
                                        <a class="checkoutMultiple" href="{{urls.checkout.multiple_address}}">
                                            {{lang 'cart.preview.checkout_multiple'}}
                                        </a>
                                    {{/if}}
                                </div>
                            {{else}}
                                <div class="cart-actions">
                                    <a class="button" href="{{urls.home}}" title="{{lang 'cart.continue_shopping'}}">{{lang 'cart.continue_shopping'}}</a>
                                </div>
                            {{/if}}

                            <!--
                            {{#if cart.additional_checkout_buttons}}
                                <div class="cart-additionalCheckoutButtons">
                                    {{#each cart.additional_checkout_buttons}}
                                        {{{this}}}
                                    {{/each}}
                                </div>
                            {{/if}}
                            -->
                        </div>
                        <div class="coupons-container">

                            <div class="accordion-block">
                                <div
                                    class="accordion-navigation"
                                    role="button"
                                    data-collapsible="#accordion--coupons">
                                    <h4 class="coupons-accordion-title">
                                        {{lang 'cart.coupons.title'}}
                                    </h4>

                                    <div class="accordion-navigation-actions">
                                        <svg class="icon accordion-indicator toggleLink-text toggleLink-text--off">
                                            <use xlink:href="#icon-chevron-down" />
                                        </svg>
                                        <svg class="icon accordion-indicator toggleLink-text toggleLink-text--on">
                                            <use xlink:href="#icon-chevron-down" />
                                        </svg>
                                    </div>
                                </div>

                                <div id="accordion--coupons" class="accordion-content">
                                    <div class="grid-bg">
                                        <div class="container">
                                            <ul class="cart-totals">
                                                {{#if cart.coupons}}
                                                    {{#each cart.coupons}}
                                                        <li class="cart-total">
                                                            <div class="cart-total-label">
                                                                <strong>{{lang 'cart.coupons.code_label' code=code}}</strong>
                                                                <div>
                                                                    <a href="{{remove_url}}">{{lang 'cart.coupons.remove'}}</a>
                                                                </div>
                                                            </div>
                                                            <div class="cart-total-value">
                                                                <span>{{discount.formatted}}</span>
                                                            </div>
                                                        </li>
                                                    {{/each}}
                                                {{else}}
                                                    <li class="cart-total">
                                                        <div class="cart-total-label">
                                                            <strong>{{lang 'cart.coupon_code'}}:</strong>
                                                        </div>
                                                        {{> components/cart/coupon-input}}
                                                    </li>
                                                {{/if}}
                                                    {{#if settings.gift_certificates_enabled}}
                                                        {{#each cart.gift_certificates}}
                                                            <li class="cart-total">
                                                                <div class="cart-total-label">
                                                                    <strong>{{lang 'cart.gift_certificates.code_label' code=code}}</strong>
                                                                    <span>
                                                                        {{remaining.formatted}} | <a href="{{remove_url}}">{{lang 'cart.gift_certificates.remove'}}</a>
                                                                    </span>
                                                                </div>
                                                                <div class="cart-total-value">
                                                                    {{used.formatted}}
                                                                </div>
                                                            </li>
                                                        {{/each}}
                                                        <li class="cart-total">
                                                            <div class="cart-total-label">
                                                                <strong>{{lang 'cart.gift_certificates.gift_certificate'}}:</strong>
                                                            </div>
                                                            {{> components/cart/gift-certificate-input}}
                                                        </li>
                                                    {{/if}}
                                                </ul>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {{{region name="cart_below_totals"}}}
                        {{{region name="cart_below_totals_permanent"}}}
                    </div>
                </div>

            {{else}}
                <h3>{{lang 'cart.checkout.empty_cart'}}</h3>
            {{/if}}
        </main>
    </div>
</div>
{{/partial}}
{{> layout/base}}

components/cart/item-giftwrap:
{{#if show_gift_wrapping}}
    <dl class="cart-item-options cart-item-options--giftWrapping">
        <dt class="cart-item-option-title">
            {{lang 'cart.gift_wrapping.title'}}:
        </dt>
        {{#if gift_wrapping}}
            <dd class="cart-item-option-description">
                {{gift_wrapping.name}}: {{gift_wrapping.price.formatted}}
                <span class="cart-item-option-actions">
                    (<a href="" data-item-giftwrap="{{id}}">{{lang 'cart.gift_wrapping.change'}}</a> or <a href="{{gift_wrapping.remove_url}}" onclick="return confirm('{{lang 'cart.gift_wrapping.remove_confirm'}}')">{{lang 'cart.gift_wrapping.remove'}}</a>)
                </span>
            </dd>
            {{#if gift_wrapping.message}}
                <dt class="cart-item-option-title">
                    {{lang 'cart.gift_wrapping.gift_message'}}:
                </dt>
                <dd class="cart-item-option-description">
                    {{gift_wrapping.message}}
                </dd>
            {{/if}}
        {{else}}
            <dd class="cart-item-option-description">
                <a href="" data-item-giftwrap="{{id}}">{{lang 'cart.gift_wrapping.add'}}</a>
            </dd>
        {{/if}}
    </dl>
{{/if}}

components/common/footer-escapa:
{{#if banners.bottom}}
    {{#if settings.data_tag_enabled}}
        <div class="banners" data-banner-location="bottom">
            {{#each (limit banners.bottom_metadata 1)}}
                <div class="banner" data-event-type="promotion" data-entity-id="{{this.id}}" data-name="{{this.banner-name}}" data-position="{{this.location}}" data-name="{{this.banner-name}}">
                    <div data-event-type="promotion-click">
                        {{{this.content}}}
                    </div>
                </div>
            {{/each}}
        </div>
    {{else}}
        <div class="banners" data-banner-location="bottom">
            <div class="banner">
                {{{limit banners.bottom 1}}}
            </div>
        </div>
    {{/if}} 
{{/if}}

{{#if settings.show_newsletter_box}}
    <div class="footer-newsletter">
        <div class="container">
            {{> components/common/subscription-form}}
        </div>
    </div>
{{/if}}

<footer class="footer" role="contentinfo">
    <h2 class="footer-title-sr-only">{{lang 'footer.title'}}</h2>
    <div class="container">

        <section class="footer-info 4a616d6573">

            <article class="footer-info-col footer-info-col--small" data-section-type="footer-webPages">
                    {{{region name="column-1--global"}}}
            </article>

            <article class="footer-info-col footer-info-col--small" data-section-type="footer-webPages">
                    {{{region name="column-2--global"}}}
            </article>

            <article class="footer-info-col footer-info-col--small" data-section-type="footer-webPages">
                    {{{region name="column-3--global"}}}
            </article>

            <article class="footer-info-col footer-info-col--small" data-section-type="footer-webPages">
                    {{{region name="column-4--global"}}} 
            </article>

        </section>

        <div class="footer-copyright">

            {{{region name="column-5--global"}}} 

        </div>

    </div>
    {{{region name="ssl_site_seal--global"}}}
</footer>


<script>
    var acc = document.getElementsByClassName("accordion");
    var i;

    for (i = 0; i < acc.length; i++) {
      acc[i].addEventListener("click", function() {
        this.classList.toggle("active");
        var panel = this.nextElementSibling;
        if (panel.style.maxHeight) {
          panel.style.maxHeight = null;
        } else {
          panel.style.maxHeight = panel.scrollHeight + "px";
        } 
      });
    }
</script>

components/products/price-card:
{{!-- There are 2 code paths for generating the PDP pricing HTML determined by the following #and condition.
If a 'price_range' exists then we generate all HTML in price-range.html, otherwise it is defined here. Both code
paths generate the same HTML structure with some differences in whether that element is displayed by default (css styling).

If you are making a change here or in price-range.html, you probably want to make that change in both files. --}}

{{#and price.price_range (if theme_settings.price_ranges '==' true)}}
    {{> components/products/price-range-card price=price}}
{{else}}
    {{#if price.with_tax}}
        <div class="price-section price-section--withTax" {{#if schema_org}}itemprop="offers" itemscope itemtype="http://schema.org/Offer"{{/if}}>
            <span class="price-section price-section--withTax non-sale-price--withTax" {{#unless price.non_sale_price_with_tax}}style="display: none;"{{/unless}}>
                <div class="old-price">
                    <span data-product-non-sale-price-with-tax class="price price--non-sale">
                        {{price.non_sale_price_with_tax.formatted}}
                    </span>
                    {{#if price.non_sale_price_with_tax}}
                        <span class="saving">
                            {{lang 'products.saving' saving_amount=(toFixed (subtract price.non_sale_price_with_tax.value price.sale_price_with_tax.value) 2)}}
                        </span>
                    {{/if}}
                </div>
            </span>
            <span data-product-price-with-tax class="price {{#if price.non_sale_price_with_tax}}red{{/if}}">{{price.with_tax.formatted}}</span>
            <div class="price-section price-section--withTax rrp-price--withTax" {{#unless price.rrp_with_tax}}style="display: none;"{{/unless}}>
                <span data-product-rrp-with-tax class="price price--rrp"> {{price.rrp_with_tax.formatted}}</span>
            </div>
            {{#if schema_org}}
                <meta itemprop="availability" itemtype="https://schema.org/ItemAvailability"
                	content="https://schema.org/{{#if product.pre_order}}PreOrder{{else if product.out_of_stock}}OutOfStock{{else if product.can_purchase '===' false}}OutOfStock{{else}}InStock{{/if}}">
                <meta itemprop="itemCondition" itemtype="https://schema.org/OfferItemCondition" content="https://schema.org/{{product.condition}}Condition">
                <meta itemprop="priceCurrency" content="{{currency_selector.active_currency_code}}">
                <meta itemprop="url" content="{{product.url}}">
                <div itemprop="priceSpecification" itemscope itemtype="https://schema.org/PriceSpecification">
                    <meta itemprop="price" content="{{price.with_tax.value}}">
                    <meta itemprop="priceCurrency" content="{{currency_selector.active_currency_code}}">
                    <meta itemprop="valueAddedTaxIncluded" content="true">
                </div>
            {{/if}}
            {{#if price.without_tax}}
                <abbr title="{{lang 'products.including_tax'}}">{{lang 'products.price_with_tax' tax_label=price.tax_label}}</abbr>
            {{/if}}
        </div>
    {{/if}}
    {{#if price.without_tax}}
        <div class="price-section price-section--withoutTax {{#if price.with_tax}}price-section--minor{{/if}}"  {{#if schema_org}}itemprop="offers" itemscope itemtype="http://schema.org/Offer"{{/if}}>
            <span class="price-section price-section--withoutTax non-sale-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}" {{#unless price.non_sale_price_without_tax}}style="display: none;"{{/unless}}>
                <span data-product-non-sale-price-without-tax class="price price--non-sale">
                    {{price.non_sale_price_without_tax.formatted}}
                </span>
            </span>
            <span data-product-price-without-tax class="price price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}">{{price.without_tax.formatted}}</span>
            <div class="price-section price-section--withoutTax rrp-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}" {{#unless price.rrp_without_tax}}style="display: none;"{{/unless}}>
                <span data-product-rrp-without-tax class="price price--rrp">{{price.rrp_without_tax.formatted}}</span>
            </div>
            {{#if schema_org}}
                <meta itemprop="availability" itemtype="https://schema.org/ItemAvailability"
                    content="https://schema.org/{{#if product.pre_order}}PreOrder{{else if product.out_of_stock}}OutOfStock{{else if product.can_purchase '===' false}}OutOfStock{{else}}InStock{{/if}}">
                <meta itemprop="itemCondition" itemtype="https://schema.org/OfferItemCondition" content="https://schema.org/{{product.condition}}Condition">
                <meta itemprop="priceCurrency" content="{{currency_selector.active_currency_code}}">
                <meta itemprop="url" content="{{product.url}}">
                <div itemprop="priceSpecification" itemscope itemtype="https://schema.org/PriceSpecification">
                    <meta itemprop="price" content="{{price.without_tax.value}}">
                    <meta itemprop="priceCurrency" content="{{currency_selector.active_currency_code}}">
                    <meta itemprop="valueAddedTaxIncluded" content="false">
                </div>
            {{/if}}
            {{#if price.with_tax}}
                <abbr title="{{lang 'products.excluding_tax'}}">{{lang 'products.price_without_tax' tax_label=price.tax_label}}</abbr>
            {{/if}}
        </div>
    {{/if}}
    {{#if page_type '===' 'product'}}
         <div class="price-section price-section--saving price" {{#unless price.saved}}style="display: none;"{{/unless}}>
                <span class="price">{{lang 'products.you_save_opening_text'}}</span>
                <span data-product-price-saved class="price price--saving">
                    {{price.saved.formatted}}
                </span>
                <span class="price">{{lang 'products.you_save_closing_bracket'}}</span>
         </div>
    {{/if}}
{{/and}}

components/products/bulk-discount-rates:
{{#if bulk_discount_rates.length}}
    <dt class="productView-info-bulkPricing-name">{{lang 'products.bulk_pricing.title'}}</dt>
    <dd class="productView-info-value">
        <p>{{lang 'products.bulk_pricing.instructions'}}</p>
        <ul>
            {{#each bulk_discount_rates}}
            <li>
                {{lang 'products.bulk_pricing.range' min=min max=max}}
                {{#if type '===' 'percent'}}
                {{lang 'products.bulk_pricing.percent' discount=discount.formatted}}
                {{else if type '===' 'fixed'}}
                {{lang 'products.bulk_pricing.fixed' discount=discount.formatted}}
                {{else if type '===' 'price'}}
                {{lang 'products.bulk_pricing.price' discount=discount.formatted}}
                {{/if}}
            </li>
            {{/each}}
        </ul>
    </dd>
{{/if}}

components/products/price-range-card:
{{#and price.retail_price_range.min.with_tax price.retail_price_range.max.with_tax}}
    <div class="price-section price-section--withTax rrp-price--withTax">
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-retail-price-label
                fallback=(lang "page_builder.pdp-retail-price-label")
            }}
        </span>
        <span data-product-rrp-price-with-tax class="price price--rrp">{{price.retail_price_range.min.with_tax.formatted}} - {{price.retail_price_range.max.with_tax.formatted}}</span>
    </div>
{{else}}
    {{#if price.with_tax}}
        <div class="price-section price-section--withTax rrp-price--withTax" style="display: none;">
            <span>
                {{> components/products/price-label
                    label_value=theme_settings.pdp-retail-price-label
                    fallback=(lang "page_builder.pdp-retail-price-label")
                }}
            </span>
            <span data-product-rrp-with-tax class="price price--rrp">
                {{price.rrp_with_tax.formatted}}
            </span>
        </div>
    {{/if}}
{{/and}}
{{#and price.price_range.min.with_tax price.price_range.max.with_tax}}
    {{!-- Never display the "non-sales price" if there is a price range to be shown, but we do want the element on the page --}}
    <div class="price-section price-section--withTax non-sale-price--withTax" style="display: none;">
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-non-sale-price-label
                fallback=(lang "page_builder.pdp-non-sale-price-label")
            }}
        </span>
        <div class="old-price">
            <span data-product-non-sale-price-with-tax class="price price--non-sale">
                {{price.non_sale_price_with_tax.formatted}}
            </span>
            {{#if price.non_sale_price_with_tax}}
                <span class="saving">
                    {{lang 'products.saving' saving_amount=(toFixed (subtract price.non_sale_price_with_tax.value price.sale_price_with_tax.value) 2)}}
                </span>
            {{/if}}
        </div>
    </div>
    <div class="price-section price-section--withTax range">
        <span class="price-label">{{theme_settings.pdp-price-label}}</span>
        <span class="price-now-label" style="display: none;">
            {{> components/products/price-label
                label_value=theme_settings.pdp-sale-price-label
                fallback=(lang "page_builder.pdp-sale-price-label")
            }}
        </span>
        <span class="from">Desde</span>
        <span data-product-price-with-tax class="price price--withTax">{{price.price_range.min.with_tax.formatted}} </span>
        {{#and price.price_range.min.without_tax price.price_range.max.without_tax}}
            <abbr title="{{lang 'products.including_tax'}}">{{lang 'products.price_with_tax' tax_label=price.price_range.min.tax_label}}</abbr>
        {{/and}}
    </div>
{{/and}}
{{#and price.retail_price_range.min.without_tax price.retail_price_range.max.without_tax}}
    <div class="price-section price-section--withoutTax rrp-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}">
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-retail-price-label
                fallback=(lang "page_builder.pdp-retail-price-label")
            }}
        </span>
        <span data-product-rrp-price-without-tax class="price price--rrp">{{price.retail_price_range.min.without_tax.formatted}} - {{price.retail_price_range.max.without_tax.formatted}}</span>
    </div>
{{else}}
    {{#if price.without_tax}}
        <div class="price-section price-section--withoutTax rrp-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}" style="display: none;">
            <span>
                {{> components/products/price-label
                    label_value=theme_settings.pdp-retail-price-label
                    fallback=(lang "page_builder.pdp-retail-price-label")
                }}
            </span>
            <span data-product-rrp-price-without-tax class="price price--rrp">
                {{price.rrp_without_tax.formatted}}
            </span>
        </div>
    {{/if}}
{{/and}}
{{#and price.price_range.min.without_tax price.price_range.max.without_tax}}
    {{!-- Never display the "non-sales price" if there is a price range to be shown, but we do want the element on the page --}}
    <div class="price-section price-section--withoutTax non-sale-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}" style="display: none;">
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-non-sale-price-label
                fallback=(lang "page_builder.pdp-non-sale-price-label")
            }}
        </span>
        <span data-product-non-sale-price-without-tax class="price price--non-sale">
            {{price.non_sale_price_without_tax.formatted}}
        </span>
    </div>
    <div class="price-section price-section--withoutTax{{#and price_range.min.with_tax price_range.max.with_tax}} price-section--minor{{/and}}">
        <span class="price-label">{{theme_settings.pdp-price-label}}</span>
        <span class="price-now-label" style="display: none;">
            {{> components/products/price-label
                label_value=theme_settings.pdp-sale-price-label
                fallback=(lang "page_builder.pdp-sale-price-label")
            }}
        </span>
        <span data-product-price-without-tax class="price price--withoutTax">{{price.price_range.min.without_tax.formatted}} - {{price.price_range.max.without_tax.formatted}}</span>
        {{#and price.price_range.min.with_tax price.price_range.max.with_tax}}
            <abbr title="{{lang 'products.excluding_tax'}}">{{lang 'products.price_without_tax' tax_label=price.price_range.min.tax_label}}</abbr>
        {{/and}}
    </div>
{{/and}}

{{!-- Never display the "saving price" element by default if there is a price range on the page to be shown --}}
{{#if page_type '===' 'product'}}
     <div class="price-section price-section--saving price" style="display: none;">
            <span class="price">{{lang 'products.you_save_opening_text'}}</span>
            <span data-product-price-saved class="price price--saving">
                {{price.saved.formatted}}
            </span>
            <span class="price">{{lang 'products.you_save_closing_bracket'}}</span>
     </div>
{{/if}}

components/common/currency-selector:
{{#if currency_selector.currencies.length '>' 1}}
    <li class="navUser-item navUser-item-currency">
        <a class="navUser-action navUser-action--currencySelector has-dropdown" href="#" data-dropdown="currencySelection" aria-controls="currencySelection" aria-expanded="false">{{lang 'common.currency' code=currency_selector.active_currency_code}} <i class="icon" aria-hidden="true"><svg><use xlink:href="#icon-downselector-small" /></svg></i></a>
        <ul class="dropdown-menu" id="currencySelection" data-dropdown-content aria-hidden="true" tabindex="-1">
            {{#each currency_selector.currencies}}
            <li class="dropdown-menu-item">
                <a href="{{{switch_url}}}"
                   data-currency-code="{{{code}}}"
                   {{#if cart_currency_switch_url.length '>' 0 }}
                   data-cart-currency-switch-url="{{{cart_currency_switch_url}}}"
                   {{/if}}
                   data-warning="{{lang 'common.currency_switch_promotion'}}"
                >
                {{#if is_active}}
                    <strong>{{name}}</strong>
                {{else}}
                    {{name}}
                {{/if}}
                </a>
            </li>
            {{/each}}
        </ul>
    </li>
{{/if}}

components/common/navigation-list:
{{#if children}}
<a class="navPages-action has-subMenu{{#if is_active}} activePage{{/if}}"
   href="{{url}}"
   data-collapsible="navPages-{{id}}"
>
    {{name}}
    <i class="icon navPages-action-moreIcon" aria-hidden="true">
        <svg><use xlink:href="#icon-chevron-down" /></svg>
    </i>
</a>
<div class="column-menu navPage-subMenu" id="navPages-{{id}}" aria-hidden="true" tabindex="-1">
    <ul class="navPage-subMenu-list">
        {{#each children}}
            <li class="navPage-subMenu-item">
                <i class="icon navPages-action-moreIcon" aria-hidden="true"><svg><use xlink:href="#icon-chevron-right" /></svg></i>
                <a class="navPage-subMenu-action navPages-action{{#if is_active}} activePage{{/if}}" href="{{url}}">{{name}}</a>
                {{#if children}}
                    <i class="icon navPages-action-moreIcon navPages-action-closed" aria-hidden="true"><svg><use xlink:href="#icon-plus" /></svg></i>
                    <i class="icon navPages-action-moreIcon navPages-action-open" aria-hidden="true"><svg><use xlink:href="#icon-minus" /></svg></i>
                {{/if}}

            </li>
            {{#if children}}
                {{#each children}}
                    <li class="navPage-childList-item">
                        <a class="navPage-childList-action navPages-action{{#if is_active}} activePage{{/if}}" href="{{url}}">{{name}}</a>
                    </li>
                {{/each}}
            {{/if}}
        {{/each}}
    </ul>
